package hasher

import "hash/maphash"

var instance = NewHasher()

func Reseed(id string) {
	instance.Reseed(id)
}

func HashFunc() func(id, str string) uint64 {
	return instance.HashFunc()
}

type hasher struct {
	seeds map[string]maphash.Seed
}

func NewHasher() *hasher {
	h := new(hasher)
	h.seeds = make(map[string]maphash.Seed)
	return h
}

// Reseed generates a new seed for the given id
func (h *hasher) Reseed(id string) {
	h.seeds[id] = maphash.MakeSeed()
}

// HashFunc returns a function that hashes a string using the seed for the given id
func (h *hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		var hash maphash.Hash
		var seed maphash.Seed
		var ok bool
		if seed, ok = h.seeds[id]; !ok {
			seed = maphash.MakeSeed()
			h.seeds[id] = seed
		}
		hash.SetSeed(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}
package hasher_test

import (
	"testing"

	"github.com/navidrome/navidrome/utils/hasher"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

func TestHasher(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Hasher Suite")
}

var _ = Describe("HashFunc", func() {
	const input = "123e4567e89b12d3a456426614174000"

	It("hashes the input and returns the sum", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		Expect(sum > 0).To(BeTrue())
	})

	It("hashes the input, reseeds and returns a different sum", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		hasher.Reseed("1")
		sum2 := hashFunc("1", input)
		Expect(sum).NotTo(Equal(sum2))
	})

	It("keeps different hashes for different ids", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		sum2 := hashFunc("2", input)

		Expect(sum).NotTo(Equal(sum2))

		Expect(sum).To(Equal(hashFunc("1", input)))
		Expect(sum2).To(Equal(hashFunc("2", input)))
	})
})

package hasher

import (
	"crypto/rand"
	"encoding/hex"
	"hash/maphash"
	"sync"
)

var globalMaphashSeed = maphash.MakeSeed()
var instance = NewHasher()

// Hasher maintains an independent seed for each identifier.
type Hasher struct {
	mu      sync.Mutex
	seeds   map[string]string
	hashSeed maphash.Seed
}

// NewHasher returns a hasher ready to generate hashes.
func NewHasher() *Hasher {
	return &Hasher{
		seeds:    make(map[string]string),
		hashSeed: globalMaphashSeed,
	}
}

// SetSeed assigns a deterministic seed to an identifier on the global hasher.
func SetSeed(id, seed string) {
	instance.SetSeed(id, seed)
}

// Reseed assigns a newly generated seed to an identifier on the global hasher.
func Reseed(id string) {
	instance.Reseed(id)
}

// HashFunc returns a function that hashes a string using the seed for its ID.
func HashFunc() func(id, str string) uint64 {
	return instance.HashFunc()
}

// SetSeed assigns the specified seed to an identifier.
func (h *Hasher) SetSeed(id, seed string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.seeds == nil {
		h.seeds = make(map[string]string)
	}
	h.seeds[id] = seed
}

// Reseed generates a new seed for the given ID.
func (h *Hasher) Reseed(id string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.seeds == nil {
		h.seeds = make(map[string]string)
	}
	previous := h.seeds[id]
	seed := randomSeed()
	for seed == previous {
		seed = randomSeed()
	}
	h.seeds[id] = seed
}

// HashFunc returns a function that hashes a string using the seed for the given ID.
func (h *Hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		seed, hashSeed := h.seedFor(id)

		var hash maphash.Hash
		hash.SetSeed(hashSeed)
		_, _ = hash.WriteString(seed)
		_, _ = hash.WriteString("\x00")
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}

func (h *Hasher) seedFor(id string) (string, maphash.Seed) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.seeds == nil {
		h.seeds = make(map[string]string)
	}
	seed, ok := h.seeds[id]
	if !ok {
		seed = randomSeed()
		h.seeds[id] = seed
	}
	return seed, h.hashSeed
}

func randomSeed() string {
	var seed [16]byte
	_, _ = rand.Read(seed[:])
	return hex.EncodeToString(seed[:])
}

