	defer h.mu.Unlock()
	if h.seeds == nil {
		h.seeds = make(map[string]string)
	}
	h.seeds[id] = seed
}

// Reseed generates a new seed for the given ID.
func (h *Hasher) Reseed(id string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.seeds == nil {
		h.seeds = make(map[string]string)
	}
	previous := h.seeds[id]
	seed := randomSeed()
	for seed == previous {
		seed = randomSeed()
	}
	h.seeds[id] = seed
}

