	h.mu.Lock()
	defer h.mu.Unlock()
	if h.seeds == nil {
		h.seeds = make(map[string]string)
	}
	if !h.seedSet {
		h.hashSeed = globalMaphashSeed
		h.seedSet = true
	}
	seed, ok := h.seeds[id]
	if !ok {
		seed = randomSeed()
		h.seeds[id] = seed
	}
	return seed, h.hashSeed
}

